// --- КОМПОНЕНТ ПЕРЕВОДА ОТВЕТОВ ИИ (AI ASSISTANT RESPONSE TRANSLATOR) ---
  const STORAGE_KEY_RESP_AUTO = 'ag_response_auto_translate';
